133	// adoptPendingReviewMarkerInto reads any pending review marker and applies it
134	// to the given session state. Returns (newState, modified, error). If the
135	// state already has Kind set (e.g., a subsequent turn of a review session),
136	// the marker is left in place and modified=false — adoption only happens on
137	// first tag. The marker is cleared on successful first adoption.
138	func adoptPendingReviewMarkerInto(ctx context.Context, s session.State) (session.State, bool, error) {
139		// Already tagged — don't re-apply on subsequent turns.
140		if s.Kind != "" {
141			return s, false, nil
142		}
143		m, ok, err := ReadPendingReviewMarker()
144		if err != nil {
145			return s, false, err
146		}
147		if !ok {
148			return s, false, nil
149		}
150		s.Kind = session.KindReview
151		s.ReviewSkills = m.Skills
152		if err := ClearPendingReviewMarker(); err != nil {
153			// Tagging succeeded; leftover marker self-heals on next session start
154			// (since Kind is now set, the next turn will return modified=false
155			// and the marker will be re-cleared on any next review session).
156			logging.Warn(ctx, "failed to clear pending review marker", slog.String("error", err.Error()))
157		}
158		return s, true, nil
159	}
