161	// runReviewConfigPicker presents a huh multi-select for each installed agent
162	// that has curated review skills, and saves the selection to
163	// .entire/settings.json. Previously-saved skills are pre-checked via
164	// huh.Option.Selected(true), mirroring how `entire enable` preserves prior
165	// selections in its own agent picker.
166	func runReviewConfigPicker(ctx context.Context, out io.Writer) (map[string][]string, error) {
167		installed := GetAgentsWithHooksInstalled(ctx)
168		if len(installed) == 0 {
169			return nil, errors.New("no agents installed; run 'entire enable' first")
170		}
171	
172		// Narrow to agents that have a curated skills list; others need manual
173		// editing of settings.json under review.<agent-name>.
174		type configurableAgent struct {
175			name types.AgentName
176			ag   agent.Agent
177		}
178		var configurable []configurableAgent
179		for _, name := range installed {
180			curated, ok := curatedReviewSkills[string(name)]
181			if !ok || len(curated) == 0 {
182				continue
183			}
184			ag, err := agent.Get(name)
185			if err != nil {
186				continue
187			}
188			configurable = append(configurable, configurableAgent{name: name, ag: ag})
189		}
190		if len(configurable) == 0 {
191			return nil, errors.New(
192				"no installed agents have curated review skills; " +
193					"edit .entire/settings.json directly under review.<agent-name>",
194			)
195		}
196	
197		// Load existing config so we can pre-check saved skills.
198		existing := map[string][]string{}
199		if s, err := settings.Load(ctx); err == nil && s != nil {
200			existing = s.Review
201		}
202	
203		// Up-front header: make the order and count obvious so users can spot
204		// when an agent they expected isn't being offered (e.g., hooks not
205		// installed for it yet).
206		labels := make([]string, 0, len(configurable))
207		for _, c := range configurable {
208			labels = append(labels, string(c.ag.Type()))
209		}
210		fmt.Fprintf(out, "Configuring review skills for %d agent(s): %s\n", len(configurable), strings.Join(labels, ", "))
211		fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Space to toggle, enter to confirm.)")
212		fmt.Fprintln(out)
213	
214		selected := map[string][]string{}
215		for i, c := range configurable {
216			curated := curatedReviewSkills[string(c.name)]
217			savedSet := map[string]struct{}{}
218			for _, s := range existing[string(c.name)] {
219				savedSet[s] = struct{}{}
220			}
221	
222			options := make([]huh.Option[string], 0, len(curated))
223			for _, s := range curated {
224				opt := huh.NewOption(fmt.Sprintf("%s — %s", s.Name, s.Desc), s.Name)
225				if _, ok := savedSet[s.Name]; ok {
226					opt = opt.Selected(true)
227				}
228				options = append(options, opt)
229			}
230	
231			// huh populates picks from Option.Selected(true) — do NOT pre-seed,
232			// matching the convention used in detectOrSelectAgent (setup.go).
233			var picks []string
234			title := fmt.Sprintf("[%d/%d] Review skills for %s", i+1, len(configurable), c.ag.Type())
235			form := NewAccessibleForm(huh.NewGroup(
236				huh.NewMultiSelect[string]().
237					Title(title).
238					Description(fmt.Sprintf("Agent: %s", c.ag.Type())).
239					Options(options...).
240					Value(&picks),
241			))
242			if err := form.Run(); err != nil {
243				return nil, fmt.Errorf("picker for %s: %w", c.name, err)
244			}
245			if len(picks) > 0 {
246				selected[string(c.name)] = picks
247			}
248		}
249		if len(selected) == 0 {
250			return nil, errors.New("no review skills selected")
251		}
252		if err := saveReviewConfig(ctx, selected); err != nil {
253			return nil, err
254		}
255		fmt.Fprintln(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.")
256		return selected, nil
257	}
