259	func newReviewCmd() *cobra.Command {
260		var edit bool
261		var trackOnly bool
262	
263		cmd := &cobra.Command{
264			Use:   "review",
265			Short: "Run configured review skills against the current branch",
266			Long: `Run the review skills configured in .entire/settings.json against
267	the current branch. On first run, an interactive picker writes the config.
268	
269	The review session is recorded as part of the next checkpoint, so the
270	review metadata is permanently attached to the commit it covers.`,
271			RunE: func(cmd *cobra.Command, _ []string) error {
272				ctx := cmd.Context()
273				if edit {
274					_, err := runReviewConfigPicker(ctx, cmd.OutOrStdout())
275					return err
276				}
277				return runReview(ctx, cmd, trackOnly)
278			},
279		}
280		cmd.Flags().BoolVar(&edit, "edit", false, "re-open the review config picker")
281		cmd.Flags().BoolVar(&trackOnly, "track-only", false, "write pending marker without spawning agent")
282		return cmd
283	}
284	
285	func runReview(ctx context.Context, cmd *cobra.Command, trackOnly bool) error {
286		out := cmd.OutOrStdout()
287	
288		// 1. Pre-flight: must be in a git repo.
289		if _, err := paths.WorktreeRoot(ctx); err != nil {
290			cmd.SilenceUsage = true
291			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
292			return NewSilentError(errors.New("not a git repository"))
293		}
294	
295		// 2. Load config; trigger first-run picker if missing.
296		s, err := settings.Load(ctx)
297		if err != nil || s == nil || len(s.Review) == 0 {
298			picked, pickErr := runReviewConfigPicker(ctx, out)
299			if pickErr != nil {
300				return pickErr
301			}
302			s = &settings.EntireSettings{Review: picked}
303		}
304	
305		// 3. Pick agent.
306		agentName, skills, err := selectReviewAgent(s.Review)
307		if err != nil {
308			return err
309		}
310	
311		// 4. Re-run guard: check if HEAD's checkpoint already has a review.
312		if reviewed, meta := headHasReviewCheckpoint(ctx); reviewed {
313			var proceed bool
314			form := NewAccessibleForm(huh.NewGroup(
315				huh.NewConfirm().
316					Title(fmt.Sprintf("Already reviewed: %s. Proceed anyway?", meta)).
317					Value(&proceed),
318			))
319			if err := form.Run(); err != nil {
320				fmt.Fprintln(out, "prompt cancelled")
321				return err //nolint:wrapcheck // propagate huh cancellation
322			}
323			if !proceed {
324				fmt.Fprintln(out, "Review cancelled.")
325				return nil
326			}
327		}
328	
329		// 5. Resolve HEAD for the pending marker.
330		headSHA, err := currentHeadSHA(ctx)
331		if err != nil {
332			return fmt.Errorf("resolve HEAD: %w", err)
333		}
334	
335		// 6. Write pending marker (agent hook will adopt it).
336		if err := WritePendingReviewMarker(PendingReviewMarker{
337			AgentName:   agentName,
338			Skills:      skills,
339			StartingSHA: headSHA,
340			StartedAt:   time.Now().UTC(),
341		}); err != nil {
342			return fmt.Errorf("write pending marker: %w", err)
343		}
344	
345		if trackOnly {
346			fmt.Fprintln(out, "Pending review marker written.")
347			fmt.Fprintf(out, "Start %s and run these skills manually: %s\n", agentName, strings.Join(skills, ", "))
348			return nil
349		}
350	
351		// 7. Spawn agent with the composed initial prompt.
352		launcher, ok := agent.LauncherFor(types.AgentName(agentName))
353		if !ok {
354			fmt.Fprintf(out, "%s does not support subprocess launch yet. Falling back to --track-only.\n", agentName)
355			fmt.Fprintf(out, "Start %s manually and run: %s\n", agentName, strings.Join(skills, ", "))
356			return nil
357		}
358		prompt := composeReviewPrompt(skills)
359		execCmd, err := launcher.LaunchCmd(ctx, prompt)
360		if err != nil {
361			return fmt.Errorf("launch %s: %w", agentName, err)
362		}
363		if err := execCmd.Run(); err != nil {
364			// Best-effort cleanup: clear the pending marker so a stale marker
365			// doesn't tag the next non-review session.
366			_ = ClearPendingReviewMarker() //nolint:errcheck // best-effort cleanup
367			return fmt.Errorf("agent exited: %w", err)
368		}
369		return nil
370	}
