372	// selectReviewAgent picks an agent from the configured review map. v1: single
373	// agent. If multiple are configured, returns the one that sorts first by name
374	// (deterministic default). Returns an error if the map is empty.
375	func selectReviewAgent(review map[string][]string) (string, []string, error) {
376		if len(review) == 0 {
377			return "", nil, errors.New("no review skills configured")
378		}
379		// Deterministic pick: alphabetical by agent name.
380		var names []string
381		for name, skills := range review {
382			if len(skills) > 0 {
383				names = append(names, name)
384			}
385		}
386		if len(names) == 0 {
387			return "", nil, errors.New("no review skills configured")
388		}
389		sort.Strings(names)
390		pick := names[0]
391		return pick, review[pick], nil
392	}
