404	// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
405	func currentHeadSHA(ctx context.Context) (string, error) {
406		repoRoot, err := paths.WorktreeRoot(ctx)
407		if err != nil {
408			return "", fmt.Errorf("locate repo root: %w", err)
409		}
410		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
411		output, err := execCmd.Output()
412		if err != nil {
413			return "", fmt.Errorf("git rev-parse HEAD: %w", err)
414		}
415		return strings.TrimSpace(string(output)), nil
416	}
417	
418	// headHasReviewCheckpoint checks whether HEAD's checkpoint metadata includes
419	// a review session. Returns (true, infoString) if HasReview is set.
420	// This is O(1): read the Entire-Checkpoint trailer from HEAD, then read the
421	// CheckpointSummary from entire/checkpoints/v1.
422	func headHasReviewCheckpoint(ctx context.Context) (bool, string) {
423		repoRoot, err := paths.WorktreeRoot(ctx)
424		if err != nil {
425			return false, ""
426		}
427		// Read HEAD commit message to extract checkpoint trailer.
428		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "-1", "--format=%B")
429		output, err := execCmd.Output()
430		if err != nil {
431			return false, ""
432		}
433		cpID, ok := trailers.ParseCheckpoint(string(output))
434		if !ok {
435			return false, ""
436		}
437		repo, err := git.PlainOpen(repoRoot)
438		if err != nil {
439			return false, ""
440		}
441		store := checkpoint.NewGitStore(repo)
442		summary, err := store.ReadCommitted(ctx, cpID)
443		if err != nil || summary == nil {
444			return false, ""
445		}
446		if !summary.HasReview {
447			return false, ""
448		}
449		// Build a short description for the re-run prompt.
450		return true, fmt.Sprintf("checkpoint %s", cpID)
451	}
