453	// saveReviewConfig persists the review map into .entire/settings.json while
454	// preserving all other settings.
455	func saveReviewConfig(ctx context.Context, review map[string][]string) error {
456		s, err := settings.Load(ctx)
457		if err != nil || s == nil {
458			s = &settings.EntireSettings{}
459		}
460		s.Review = review
461		if err := settings.Save(ctx, s); err != nil {
462			return fmt.Errorf("save settings: %w", err)
463		}
464		return nil
465	}
