139	// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
140	// Returns empty string if unable to determine.
141	func getDefaultBranchFromRemote(repo *git.Repository) string {
142		// Try to get the symbolic reference for origin/HEAD
143		ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
144		if err == nil && ref != nil {
145			// ref.Target() gives us something like "refs/remotes/origin/main"
146			target := ref.Target().String()
147			if strings.HasPrefix(target, "refs/remotes/origin/") {
148				return strings.TrimPrefix(target, "refs/remotes/origin/")
149			}
150		}
151	
152		// Fallback: check if origin/main or origin/master exists
153		if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
154			return "main"
155		}
156		if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
157			return "master"
158		}
159	
160		return ""
161	}
